/* TOOEZ - "Đọc trước, học sau": bài đọc Part 7 có nghĩa theo ngữ cảnh, bản dịch mẫu và các cặp paraphrase câu hỏi ↔ bài. Tạo bằng tools/docread_data.py */
window.DOCREAD=[{"id": "dr-chairs", "set": "p7-set1", "title": "Ghế văn phòng tạm hết hàng", "kind": "E-mail", "paras": [{"en": "From: Laura Chen, Brightway Office Supplies. To: Daniel Ortiz. Date: March 3. Subject: Your order #4471", "vi": "Từ: Laura Chen, Văn phòng phẩm Brightway. Gửi: Daniel Ortiz. Ngày: 3/3. Tiêu đề: Đơn hàng số 4471 của ông"}, {"en": "Dear Mr. Ortiz,", "vi": "Kính gửi ông Ortiz,"}, {"en": "Thank you for your recent order of 20 ergonomic desk chairs. Unfortunately, the model you selected, the ProSeat 300, is temporarily out of stock because of high demand. Our supplier expects a new shipment on March 20.", "vi": "Cảm ơn ông đã đặt 20 chiếc ghế văn phòng công thái học gần đây. Rất tiếc, mẫu ông chọn là ProSeat 300 đang tạm hết hàng do nhu cầu cao. Nhà cung cấp của chúng tôi dự kiến có lô hàng mới vào ngày 20/3."}, {"en": "We can offer you two options. First, we can hold your order and deliver the chairs as soon as they arrive, at no additional shipping cost. Alternatively, we can send you the ProSeat 350, an upgraded version, for the same price, and it can be delivered by March 8.", "vi": "Chúng tôi có thể đưa ra hai lựa chọn. Thứ nhất, chúng tôi giữ lại đơn hàng và giao ghế ngay khi hàng về, không tính thêm phí vận chuyển. Hoặc, chúng tôi gửi ông mẫu ProSeat 350, phiên bản nâng cấp, với cùng mức giá, và có thể giao trước ngày 8/3."}, {"en": "Please reply to this e-mail by March 6 to let us know your choice. If we do not hear from you, we will process the first option.", "vi": "Vui lòng trả lời e-mail này trước ngày 6/3 để cho chúng tôi biết lựa chọn của ông. Nếu không nhận được phản hồi, chúng tôi sẽ thực hiện theo lựa chọn thứ nhất."}, {"en": "Sincerely, Laura Chen, Customer Service", "vi": "Trân trọng, Laura Chen, Bộ phận Chăm sóc khách hàng"}], "gl": [{"t": "recent", "ctx": "gần đây, vừa mới", "other": ""}, {"t": "ergonomic", "ctx": "công thái học: thiết kế để ngồi đúng tư thế, đỡ mỏi", "other": ""}, {"t": "Unfortunately", "ctx": "rất tiếc là (báo tin không vui)", "other": ""}, {"t": "temporarily", "ctx": "tạm thời", "other": ""}, {"t": "out of stock", "ctx": "hết hàng", "other": ""}, {"t": "high demand", "ctx": "nhu cầu cao, nhiều người mua", "other": ""}, {"t": "supplier", "ctx": "nhà cung cấp", "other": ""}, {"t": "shipment", "ctx": "lô hàng", "other": "việc vận chuyển, gửi hàng"}, {"t": "hold your order", "ctx": "giữ đơn hàng lại, chưa giao", "other": "hold: cầm, nắm; tổ chức (hold a meeting)"}, {"t": "as soon as", "ctx": "ngay khi", "other": ""}, {"t": "at no additional shipping cost", "ctx": "không tính thêm phí vận chuyển", "other": ""}, {"t": "Alternatively", "ctx": "hoặc là, một cách khác là", "other": ""}, {"t": "upgraded version", "ctx": "phiên bản nâng cấp", "other": ""}, {"t": "delivered", "ctx": "được giao (hàng)", "other": "deliver a speech: phát biểu"}, {"t": "let us know", "ctx": "cho chúng tôi biết", "other": ""}, {"t": "process", "ctx": "xử lý, tiến hành (đơn hàng, yêu cầu)", "other": "process (n): quy trình"}, {"t": "option", "ctx": "lựa chọn, phương án", "other": ""}], "links": {"p7-147": [["a problem with an order", "temporarily out of stock"], ["a problem", "Unfortunately"]], "p7-148": [["Free shipping", "at no additional shipping cost"], ["A different model", "the ProSeat 350, an upgraded version"], ["Delivery of a product by March 8", "delivered by March 8"]], "p7-149": [["does not reply", "do not hear from you"], ["His order will be delivered after new stock arrives", "deliver the chairs as soon as they arrive"], ["will happen", "we will process the first option"]]}}, {"id": "dr-lift-notice", "set": "p7-set3", "title": "Thay thang máy chung cư", "kind": "Thông báo", "paras": [{"en": "Notice to all tenants of Maple Court Apartments", "vi": "Thông báo gửi tất cả cư dân thuê nhà tại chung cư Maple Court"}, {"en": "The main elevator in Building B will be replaced from April 10 to April 24. —[1]—. During this period, residents are asked to use the service elevator located near the rear entrance. —[2]—.", "vi": "Thang máy chính ở Tòa B sẽ được thay mới từ ngày 10/4 đến 24/4. —[1]—. Trong thời gian này, cư dân được đề nghị dùng thang máy phục vụ nằm gần cửa sau. —[2]—."}, {"en": "Because the service elevator is smaller, it may be crowded during morning hours. —[3]—. Residents who have difficulty using the stairs and need help carrying groceries or packages may contact the management office at 555-0182. —[4]—. We apologize for any inconvenience and thank you for your patience.", "vi": "Vì thang máy phục vụ nhỏ hơn nên có thể đông vào buổi sáng. —[3]—. Cư dân gặp khó khăn khi đi cầu thang bộ và cần giúp mang đồ chợ hoặc bưu kiện có thể liên hệ ban quản lý qua số 555-0182. —[4]—. Chúng tôi xin lỗi vì sự bất tiện và cảm ơn sự kiên nhẫn của quý cư dân."}], "gl": [{"t": "tenants", "ctx": "người thuê nhà", "other": ""}, {"t": "replaced", "ctx": "được thay mới", "other": "replace sb: thay thế người làm việc"}, {"t": "During this period", "ctx": "trong khoảng thời gian này", "other": ""}, {"t": "residents", "ctx": "cư dân, người sống ở đó", "other": ""}, {"t": "are asked to", "ctx": "được đề nghị, được yêu cầu", "other": ""}, {"t": "service elevator", "ctx": "thang máy phục vụ (chở hàng, cho nhân viên)", "other": ""}, {"t": "located", "ctx": "nằm ở", "other": ""}, {"t": "rear entrance", "ctx": "cửa sau", "other": ""}, {"t": "crowded", "ctx": "đông đúc", "other": ""}, {"t": "have difficulty", "ctx": "gặp khó khăn", "other": ""}, {"t": "groceries", "ctx": "đồ mua ở chợ / siêu thị (thực phẩm)", "other": ""}, {"t": "packages", "ctx": "bưu kiện, gói hàng", "other": "package: gói (dịch vụ), vd. benefits package"}, {"t": "management office", "ctx": "văn phòng ban quản lý", "other": ""}, {"t": "apologize for any inconvenience", "ctx": "xin lỗi vì mọi bất tiện", "other": ""}, {"t": "patience", "ctx": "sự kiên nhẫn", "other": ""}], "links": {"p7-152": [["a temporary change", "will be replaced from April 10 to April 24"], ["residents", "tenants"]], "p7-153": [["Contact the office", "contact the management office"], ["assistance", "need help"]], "p7-154": [["allowing extra time", "it may be crowded during morning hours"], ["when leaving for work or school", "morning hours"]]}}, {"id": "dr-lift-email", "set": "p7x-p1", "title": "Bảo trì thang máy văn phòng", "kind": "E-mail", "paras": [{"en": "From: Daniel Ortiz, Facilities Manager. To: All Staff, Harbor Point Office. Date: May 5. Subject: Elevator maintenance", "vi": "Từ: Daniel Ortiz, Quản lý cơ sở vật chất. Gửi: Toàn thể nhân viên, Văn phòng Harbor Point. Ngày: 5/5. Tiêu đề: Bảo trì thang máy"}, {"en": "Dear colleagues,", "vi": "Các đồng nghiệp thân mến,"}, {"en": "I am writing to let you know that the main elevators in the Harbor Point building will be out of service from Monday, May 12, through Wednesday, May 14.", "vi": "Tôi viết thư này để báo các bạn biết thang máy chính của tòa nhà Harbor Point sẽ ngừng hoạt động từ thứ Hai 12/5 đến hết thứ Tư 14/5."}, {"en": "During this period, technicians from Lindell Lift Services will be replacing the cables and upgrading the control panels. Staff are asked to use the freight elevator at the rear of the building or the east stairwell.", "vi": "Trong thời gian này, kỹ thuật viên của Lindell Lift Services sẽ thay cáp và nâng cấp bảng điều khiển. Nhân viên được đề nghị dùng thang máy chở hàng ở phía sau tòa nhà hoặc cầu thang bộ phía đông."}, {"en": "Please note that the freight elevator may not be used to transport furniture or large equipment during business hours. If you are expecting a delivery during these three days, please contact the front desk no later than Friday so that we can arrange an alternative drop-off point.", "vi": "Xin lưu ý: không được dùng thang máy chở hàng để vận chuyển đồ nội thất hoặc thiết bị lớn trong giờ làm việc. Nếu bạn đang chờ hàng giao tới trong ba ngày này, hãy liên hệ quầy lễ tân chậm nhất là thứ Sáu để chúng tôi sắp xếp điểm nhận hàng khác."}, {"en": "We apologize for any inconvenience and thank you for your cooperation. Daniel Ortiz", "vi": "Chúng tôi xin lỗi vì sự bất tiện và cảm ơn sự hợp tác của các bạn. Daniel Ortiz"}], "gl": [{"t": "Facilities Manager", "ctx": "quản lý cơ sở vật chất (tòa nhà, thiết bị)", "other": ""}, {"t": "maintenance", "ctx": "bảo trì", "other": ""}, {"t": "out of service", "ctx": "ngừng hoạt động", "other": ""}, {"t": "through", "ctx": "đến hết (ngày)", "other": "xuyên qua; thông qua"}, {"t": "technicians", "ctx": "kỹ thuật viên", "other": ""}, {"t": "cables", "ctx": "dây cáp", "other": ""}, {"t": "upgrading", "ctx": "nâng cấp", "other": ""}, {"t": "control panels", "ctx": "bảng điều khiển", "other": ""}, {"t": "freight elevator", "ctx": "thang máy chở hàng", "other": ""}, {"t": "at the rear of", "ctx": "ở phía sau", "other": ""}, {"t": "stairwell", "ctx": "cầu thang bộ (khoang cầu thang)", "other": ""}, {"t": "Please note", "ctx": "xin lưu ý", "other": ""}, {"t": "transport", "ctx": "vận chuyển", "other": ""}, {"t": "equipment", "ctx": "thiết bị", "other": ""}, {"t": "business hours", "ctx": "giờ làm việc", "other": ""}, {"t": "expecting a delivery", "ctx": "đang chờ hàng giao tới", "other": "expect: kỳ vọng, dự đoán"}, {"t": "front desk", "ctx": "quầy lễ tân", "other": ""}, {"t": "no later than", "ctx": "chậm nhất là", "other": ""}, {"t": "arrange", "ctx": "sắp xếp", "other": ""}, {"t": "alternative", "ctx": "khác, để thay thế", "other": ""}, {"t": "drop-off point", "ctx": "điểm nhận / gửi hàng", "other": ""}, {"t": "cooperation", "ctx": "sự hợp tác", "other": ""}], "links": {"p7x-p1-0": [["upcoming repair work", "will be out of service"], ["repair work", "replacing the cables and upgrading the control panels"]], "p7x-p1-1": [["Improve", "upgrading"], ["control systems", "control panels"]], "p7x-p1-2": [["expecting a delivery", "expecting a delivery"], ["Contact the front desk by Friday", "contact the front desk no later than Friday"]], "p7x-p1-3": [["at the back of the building", "at the rear of the building"]]}}, {"id": "dr-grocery", "set": "p7x-p3", "title": "Siêu thị mở cửa hàng thứ hai", "kind": "Bài báo", "paras": [{"en": "Greenway Market to Open Second Store", "vi": "Greenway Market sắp mở cửa hàng thứ hai"}, {"en": "Greenway Market, the family-owned grocery chain known for its locally grown produce, will open its second store on Alder Street on September 2.", "vi": "Greenway Market, chuỗi cửa hàng thực phẩm do một gia đình sở hữu, nổi tiếng với nông sản trồng tại địa phương, sẽ mở cửa hàng thứ hai trên phố Alder vào ngày 2/9."}, {"en": "The new location will be nearly twice the size of the original shop on Main Street. [1] In addition to fresh fruit and vegetables, it will feature a bakery, a coffee counter, and a small seating area.", "vi": "Cửa hàng mới sẽ rộng gần gấp đôi cửa hàng đầu tiên trên phố Main. [1] Ngoài rau quả tươi, cửa hàng còn có tiệm bánh, quầy cà phê và một khu ngồi nhỏ."}, {"en": "Owner Rita Alvarez said the expansion was driven largely by customer demand. “Shoppers have been asking us for a bigger space for years,” she said. [2]", "vi": "Chủ cửa hàng Rita Alvarez cho biết việc mở rộng chủ yếu xuất phát từ nhu cầu của khách hàng. “Khách đã đề nghị chúng tôi có không gian rộng hơn suốt nhiều năm,” bà nói. [2]"}, {"en": "To celebrate the opening, the first 100 customers will receive a free reusable shopping bag. [3]", "vi": "Để mừng khai trương, 100 khách hàng đầu tiên sẽ được tặng một túi mua sắm dùng nhiều lần. [3]"}, {"en": "The store will be open daily from 7 A.M. to 9 P.M. Parking is available in the public garage across the street. [4]", "vi": "Cửa hàng mở cửa hằng ngày từ 7 giờ sáng đến 9 giờ tối. Có chỗ đỗ xe ở bãi đỗ xe công cộng bên kia đường. [4]"}], "gl": [{"t": "family-owned", "ctx": "do một gia đình sở hữu", "other": ""}, {"t": "grocery chain", "ctx": "chuỗi cửa hàng thực phẩm", "other": ""}, {"t": "known for", "ctx": "nổi tiếng về", "other": ""}, {"t": "locally grown produce", "ctx": "nông sản trồng tại địa phương", "other": "produce (v): sản xuất"}, {"t": "location", "ctx": "địa điểm (cửa hàng, chi nhánh)", "other": ""}, {"t": "nearly twice the size", "ctx": "rộng gần gấp đôi", "other": ""}, {"t": "original", "ctx": "đầu tiên, ban đầu", "other": "nguyên bản, độc đáo"}, {"t": "In addition to", "ctx": "ngoài … ra còn", "other": ""}, {"t": "feature", "ctx": "có (đặc điểm, khu vực)", "other": "feature (n): đặc điểm, tính năng"}, {"t": "seating area", "ctx": "khu ghế ngồi", "other": ""}, {"t": "expansion", "ctx": "sự mở rộng", "other": ""}, {"t": "driven", "ctx": "được thúc đẩy (bởi lý do gì)", "other": "drive: lái xe"}, {"t": "largely", "ctx": "phần lớn, chủ yếu", "other": ""}, {"t": "customer demand", "ctx": "nhu cầu của khách hàng", "other": ""}, {"t": "celebrate", "ctx": "kỷ niệm, ăn mừng", "other": ""}, {"t": "reusable", "ctx": "dùng lại được nhiều lần", "other": ""}, {"t": "public garage", "ctx": "bãi đỗ xe công cộng (nhà xe)", "other": "garage: gara sửa xe"}, {"t": "across the street", "ctx": "bên kia đường", "other": ""}], "links": {"p7x-p3-0": [["A bakery", "a bakery"], ["A seating area", "a small seating area"], ["A coffee counter", "a coffee counter"]], "p7x-p3-1": [["a much wider range of products", "nearly twice the size"]], "p7x-p3-2": [["motivated", "driven"]], "p7x-p3-3": [["Its first store is on Main Street", "the original shop on Main Street"]]}}, {"id": "dr-hq", "set": "p7x-p6", "title": "Công ty chuyển trụ sở", "kind": "Bài báo", "paras": [{"en": "Solaro Energy to Move Headquarters", "vi": "Solaro Energy sắp chuyển trụ sở"}, {"en": "MILTON (June 4) — Solaro Energy announced on Tuesday that it will relocate its headquarters from downtown Milton to the Riverside Business Park by the end of next year.", "vi": "MILTON (4/6) — Hôm thứ Ba, Solaro Energy thông báo sẽ chuyển trụ sở từ trung tâm thành phố Milton đến Khu kinh doanh Riverside trước cuối năm sau."}, {"en": "The company, which employs about 300 people, has outgrown its current offices on Bay Street.", "vi": "Công ty có khoảng 300 nhân viên và văn phòng hiện tại trên phố Bay đã trở nên quá chật."}, {"en": "According to CEO Hannah Weiss, the new site will allow the firm to bring its research team, currently based in a separate building, under the same roof as its administrative staff.", "vi": "Theo giám đốc điều hành Hannah Weiss, địa điểm mới sẽ giúp công ty đưa nhóm nghiên cứu, hiện đang làm ở một tòa nhà riêng, về cùng một nơi với bộ phận hành chính."}, {"en": "“Having everyone in one place will speed up how quickly we turn ideas into products,” Weiss said.", "vi": "“Có mọi người ở cùng một chỗ sẽ giúp chúng tôi biến ý tưởng thành sản phẩm nhanh hơn,” bà Weiss nói."}, {"en": "City officials welcomed the decision, noting that the company had also considered moving to a neighboring town.", "vi": "Lãnh đạo thành phố hoan nghênh quyết định này, đồng thời cho biết công ty từng cân nhắc chuyển sang một thị trấn lân cận."}], "gl": [{"t": "relocate", "ctx": "chuyển địa điểm", "other": ""}, {"t": "headquarters", "ctx": "trụ sở chính", "other": ""}, {"t": "downtown", "ctx": "khu trung tâm thành phố", "other": ""}, {"t": "Business Park", "ctx": "khu kinh doanh, khu văn phòng", "other": ""}, {"t": "employs", "ctx": "thuê, tuyển dụng (có bao nhiêu nhân viên)", "other": "employ: sử dụng (phương pháp)"}, {"t": "has outgrown", "ctx": "đã lớn quá, không còn vừa (văn phòng cũ)", "other": ""}, {"t": "current", "ctx": "hiện tại", "other": ""}, {"t": "According to", "ctx": "theo (lời ai)", "other": ""}, {"t": "site", "ctx": "địa điểm", "other": "website"}, {"t": "firm", "ctx": "công ty", "other": "firm (adj): chắc chắn, kiên quyết"}, {"t": "based in", "ctx": "đặt ở, làm việc ở", "other": ""}, {"t": "separate", "ctx": "riêng biệt", "other": ""}, {"t": "under the same roof", "ctx": "cùng một tòa nhà, cùng một chỗ", "other": ""}, {"t": "administrative staff", "ctx": "nhân viên hành chính", "other": ""}, {"t": "speed up", "ctx": "đẩy nhanh", "other": ""}, {"t": "turn ideas into products", "ctx": "biến ý tưởng thành sản phẩm", "other": ""}, {"t": "officials", "ctx": "quan chức, lãnh đạo", "other": ""}, {"t": "welcomed", "ctx": "hoan nghênh, tán thành", "other": "welcome sb: chào đón ai"}, {"t": "noting that", "ctx": "lưu ý / cho biết rằng", "other": ""}, {"t": "considered", "ctx": "đã cân nhắc", "other": ""}, {"t": "neighboring town", "ctx": "thị trấn lân cận", "other": ""}], "links": {"p7x-p6-0": [["change locations", "relocate its headquarters"]], "p7x-p6-1": [["too small", "has outgrown its current offices"]], "p7x-p6-2": [["works apart from", "based in a separate building"], ["the administrative staff", "administrative staff"]], "p7x-p6-3": [["were glad", "welcomed the decision"], ["stay in the area", "had also considered moving to a neighboring town"]]}}, {"id": "dr-hotel", "set": "p7x-p8", "title": "Đánh giá khách sạn", "kind": "Đánh giá", "paras": [{"en": "Hotel Lumen ★★★★☆ — reviewed by Carla Mendes", "vi": "Khách sạn Lumen ★★★★☆ — đánh giá của Carla Mendes"}, {"en": "I stayed at the Hotel Lumen for three nights while attending a sales conference nearby.", "vi": "Tôi ở khách sạn Lumen ba đêm trong lúc dự một hội nghị bán hàng gần đó."}, {"en": "The room was spotless, and the front-desk staff were extremely helpful when my laptop charger stopped working — they lent me one within minutes.", "vi": "Phòng sạch bong, và nhân viên lễ tân cực kỳ nhiệt tình khi sạc laptop của tôi bị hỏng: họ cho tôi mượn một cái chỉ trong vài phút."}, {"en": "The breakfast buffet offered plenty of choices, although the coffee was disappointing.", "vi": "Bữa sáng tự chọn có rất nhiều món, dù cà phê thì không ngon như mong đợi."}, {"en": "My only real complaint is the noise: my room faced a busy street, and I had trouble sleeping.", "vi": "Điều duy nhất tôi thật sự phàn nàn là tiếng ồn: phòng tôi hướng ra một con phố đông đúc, nên tôi khó ngủ."}, {"en": "Next time, I will ask for a room on the courtyard side.", "vi": "Lần sau, tôi sẽ xin một phòng ở phía sân trong."}], "gl": [{"t": "attending", "ctx": "tham dự", "other": ""}, {"t": "sales conference", "ctx": "hội nghị bán hàng", "other": ""}, {"t": "nearby", "ctx": "ở gần đó", "other": ""}, {"t": "spotless", "ctx": "sạch bong, không một vết bẩn", "other": ""}, {"t": "front-desk staff", "ctx": "nhân viên lễ tân", "other": ""}, {"t": "extremely helpful", "ctx": "cực kỳ nhiệt tình giúp đỡ", "other": ""}, {"t": "charger", "ctx": "cục sạc", "other": ""}, {"t": "lent", "ctx": "cho mượn (quá khứ của lend)", "other": "borrow: đi mượn (ngược chiều)"}, {"t": "within minutes", "ctx": "chỉ trong vài phút", "other": ""}, {"t": "plenty of choices", "ctx": "rất nhiều lựa chọn", "other": ""}, {"t": "although", "ctx": "mặc dù", "other": ""}, {"t": "disappointing", "ctx": "gây thất vọng", "other": ""}, {"t": "complaint", "ctx": "lời phàn nàn", "other": ""}, {"t": "faced", "ctx": "hướng ra, quay ra", "other": "face a problem: đối mặt với vấn đề"}, {"t": "had trouble sleeping", "ctx": "khó ngủ", "other": ""}, {"t": "courtyard side", "ctx": "phía sân trong", "other": ""}], "links": {"p7x-p8-0": [["on a business trip", "attending a sales conference"]], "p7x-p8-1": [["lent her an item", "lent me one"], ["an item", "laptop charger"]], "p7x-p8-2": [["a beverage", "the coffee"], ["disappointed", "disappointing"]], "p7x-p8-3": [["request", "ask for"], ["a different part of the hotel", "a room on the courtyard side"]]}}, {"id": "dr-recycle", "set": "e2p7-s6", "title": "Chương trình phân loại rác", "kind": "Thông báo nội bộ", "paras": [{"en": "To: All employees. From: Rachel Owens, Office Manager. Date: January 15. Re: New recycling program", "vi": "Gửi: Toàn thể nhân viên. Từ: Rachel Owens, Quản lý văn phòng. Ngày: 15/1. V/v: Chương trình tái chế mới"}, {"en": "Beginning February 1, Tarrin Corporation will introduce a new recycling program. [1]", "vi": "Từ ngày 1/2, Tập đoàn Tarrin sẽ bắt đầu áp dụng chương trình tái chế mới. [1]"}, {"en": "Each department will receive three bins: blue for paper, green for plastic and glass, and gray for general waste. [2]", "vi": "Mỗi phòng ban sẽ nhận ba thùng rác: xanh dương cho giấy, xanh lá cho nhựa và thủy tinh, xám cho rác thông thường. [2]"}, {"en": "Bins will be emptied every Tuesday and Friday by our cleaning service. [3]", "vi": "Thùng rác sẽ được dịch vụ vệ sinh đổ vào mỗi thứ Ba và thứ Sáu. [3]"}, {"en": "A short guide explaining what belongs in each bin will be sent to everyone next week. [4]", "vi": "Một bản hướng dẫn ngắn giải thích rác nào bỏ vào thùng nào sẽ được gửi cho mọi người vào tuần sau. [4]"}, {"en": "If you have any questions, please contact me at extension 214.", "vi": "Nếu có thắc mắc, vui lòng liên hệ tôi qua số máy lẻ 214."}], "gl": [{"t": "Re", "ctx": "về việc (dòng tiêu đề thư)", "other": ""}, {"t": "recycling program", "ctx": "chương trình tái chế", "other": ""}, {"t": "Beginning", "ctx": "bắt đầu từ (ngày)", "other": "beginning (n): phần đầu"}, {"t": "introduce", "ctx": "đưa vào áp dụng", "other": "introduce sb: giới thiệu ai"}, {"t": "department", "ctx": "phòng ban", "other": ""}, {"t": "bins", "ctx": "thùng (rác)", "other": ""}, {"t": "general waste", "ctx": "rác thông thường", "other": ""}, {"t": "emptied", "ctx": "được đổ (cho hết rác)", "other": ""}, {"t": "cleaning service", "ctx": "dịch vụ vệ sinh", "other": ""}, {"t": "guide", "ctx": "bản hướng dẫn", "other": "guide (n): hướng dẫn viên"}, {"t": "belongs in", "ctx": "nên được bỏ vào, thuộc về (chỗ nào)", "other": ""}, {"t": "extension", "ctx": "số máy lẻ (điện thoại)", "other": "sự gia hạn; sự mở rộng"}], "links": {"e2p7-s6-0": [["announce a new program", "will introduce a new recycling program"]], "e2p7-s6-1": [["Twice a week", "every Tuesday and Friday"]], "e2p7-s6-2": [["the blue bin", "blue for paper"], ["Large cardboard boxes", "paper"]]}}, {"id": "dr-ferry", "set": "e2p7-s10", "title": "Tuyến phà mới", "kind": "Bài báo", "paras": [{"en": "New Ferry Service to Connect Port Hale and Cliffton", "vi": "Tuyến phà mới nối Port Hale và Cliffton"}, {"en": "Business Today - June 2", "vi": "Business Today - 2/6"}, {"en": "Starting July 15, Blue Harbor Ferries will begin daily service between Port Hale and Cliffton. [1]", "vi": "Từ ngày 15/7, Blue Harbor Ferries sẽ bắt đầu chạy phà hằng ngày giữa Port Hale và Cliffton. [1]"}, {"en": "The trip will take about forty minutes, compared with nearly two hours by car. Ferries will depart every hour from 6 A.M. to 9 P.M. [2]", "vi": "Chuyến đi mất khoảng bốn mươi phút, so với gần hai tiếng nếu đi ô tô. Phà khởi hành mỗi giờ một chuyến từ 6 giờ sáng đến 9 giờ tối. [2]"}, {"en": "One-way tickets will cost $12 for adults and $6 for children under twelve. Commuters can also buy a monthly pass for $180. [3]", "vi": "Vé một chiều giá 12 đô cho người lớn và 6 đô cho trẻ dưới mười hai tuổi. Người đi làm hằng ngày cũng có thể mua vé tháng giá 180 đô. [3]"}, {"en": "Local business owners expect the service to bring more visitors to Cliffton's waterfront shops and restaurants. [4]", "vi": "Các chủ doanh nghiệp địa phương kỳ vọng tuyến phà sẽ đưa thêm khách đến các cửa hàng và nhà hàng ven biển của Cliffton. [4]"}, {"en": "“Many people avoid the drive because of traffic,” said Mayor Ellen Brooks. “The ferry will make a day trip much easier.”", "vi": "“Nhiều người ngại lái xe vì tắc đường,” Thị trưởng Ellen Brooks nói. “Có phà, đi chơi trong ngày sẽ dễ hơn nhiều.”"}], "gl": [{"t": "Ferry Service", "ctx": "dịch vụ phà", "other": ""}, {"t": "Connect", "ctx": "nối, kết nối", "other": ""}, {"t": "Starting", "ctx": "bắt đầu từ (ngày)", "other": ""}, {"t": "daily service", "ctx": "chuyến chạy hằng ngày", "other": ""}, {"t": "compared with", "ctx": "so với", "other": ""}, {"t": "nearly", "ctx": "gần, suýt soát", "other": ""}, {"t": "depart", "ctx": "khởi hành", "other": ""}, {"t": "One-way tickets", "ctx": "vé một chiều", "other": ""}, {"t": "Commuters", "ctx": "người đi làm hằng ngày (bằng xe, tàu, phà)", "other": ""}, {"t": "monthly pass", "ctx": "vé tháng", "other": ""}, {"t": "Local business owners", "ctx": "chủ doanh nghiệp địa phương", "other": ""}, {"t": "expect", "ctx": "kỳ vọng, dự đoán", "other": "expect a delivery: chờ hàng giao tới"}, {"t": "waterfront", "ctx": "ven sông / ven biển", "other": ""}, {"t": "avoid the drive", "ctx": "tránh phải lái xe", "other": ""}, {"t": "traffic", "ctx": "giao thông, tắc đường", "other": ""}, {"t": "Mayor", "ctx": "thị trưởng", "other": ""}, {"t": "a day trip", "ctx": "chuyến đi chơi trong ngày", "other": ""}], "links": {"e2p7-s10-0": [["A new transportation service", "New Ferry Service"]], "e2p7-s10-1": [["drive", "by car"], ["Nearly two hours", "nearly two hours"]], "e2p7-s10-2": [["It costs $180.", "a monthly pass for $180"]], "e2p7-s10-3": [["at no extra charge", "One-way tickets will cost $12"]]}}, {"id": "drh-foodhall", "set": "drh-foodhall", "title": "Khu ẩm thực trong nhà máy dệt cũ", "kind": "Blog", "paras": [{"en": "Marisol's Weekend Table | Posted October 14", "vi": "Bàn ăn cuối tuần của Marisol | Đăng ngày 14/10"}, {"en": "For nearly a decade, the old Corwin textile mill on Bayard Street stood vacant, its windows boarded up and its future uncertain. The property changed hands twice, and rumors that it would be converted into luxury apartments turned out to be unfounded. Last month, however, the building finally reopened as the Corwin Food Hall, and I have already visited it three times. —[1]—", "vi": "Suốt gần mười năm, nhà máy dệt Corwin cũ trên phố Bayard bị bỏ trống, cửa sổ bị bịt ván và tương lai chẳng ai rõ. Khu đất đã đổi chủ hai lần, và tin đồn rằng nó sẽ bị biến thành căn hộ cao cấp hóa ra là vô căn cứ. Thế nhưng tháng trước, tòa nhà cuối cùng đã mở cửa lại thành Khu ẩm thực Corwin, và tôi đã ghé ba lần rồi. —[1]—"}, {"en": "The developers deserve credit for preserving much of the mill's original character. The exposed timber beams, brick walls, and tall arched windows give the space a warmth that newer venues rarely achieve. Twenty-two vendors occupy stalls on the ground floor, offering everything from hand-pulled noodles to wood-fired flatbreads. Long communal tables run down the center of the hall, which encourages strangers to strike up conversations. Prices are moderate, and most dishes cost less than $15. —[2]—", "vi": "Chủ đầu tư đáng được khen vì đã giữ lại phần lớn nét đặc trưng ban đầu của nhà máy. Dầm gỗ để lộ, tường gạch và những ô cửa sổ vòm cao tạo cho không gian một sự ấm cúng mà các địa điểm mới hiếm khi có được. Hai mươi hai người bán thuê các gian hàng ở tầng trệt, bán đủ thứ từ mì kéo tay đến bánh mì dẹt nướng lò củi. Những dãy bàn dài dùng chung chạy dọc giữa sảnh, khiến người lạ dễ bắt chuyện với nhau. Giá cả vừa phải, phần lớn món dưới 15 đô. —[2]—"}, {"en": "The anchor tenant, Hollis & Grain, occupies the mezzanine overlooking the main hall. Chef Teodora Vance, who spent years cooking in acclaimed kitchens abroad, has designed a seasonal tasting menu built around produce from nearby farms. I sampled it on my second visit. —[3]— Its flavor was so remarkably rich that I asked the server whether cream had been added; it had not.", "vi": "Khách thuê chủ chốt là Hollis & Grain, nằm ở tầng lửng nhìn xuống sảnh chính. Đầu bếp Teodora Vance, người đã nhiều năm nấu ở những bếp danh tiếng ở nước ngoài, thiết kế một thực đơn nếm thử theo mùa dựa trên nông sản từ các trang trại gần đó. Tôi đã ăn thử trong lần ghé thứ hai. —[3]— Vị của nó đậm đà đến mức tôi phải hỏi người phục vụ có cho kem vào không; không hề."}, {"en": "A word of caution: Hollis & Grain has been booked solid since its opening night, so reservations should be made at least two weeks in advance. Parking is also scarce, as the mill's small lot fills up quickly on weekends. Visitors are better off taking the Route 9 bus, which stops directly across the street. —[4]— Despite these minor inconveniences, the Corwin Food Hall is a welcome addition to the neighborhood, and I suspect it will soon become a fixture of the city's dining scene.", "vi": "Một lời cảnh báo nhỏ: Hollis & Grain kín bàn từ đêm khai trương, nên cần đặt chỗ trước ít nhất hai tuần. Chỗ đỗ xe cũng khan hiếm, vì bãi nhỏ của nhà máy kín rất nhanh vào cuối tuần. Khách tốt hơn nên đi xe buýt tuyến 9, dừng ngay bên kia đường. —[4]— Dù có vài bất tiện nhỏ, Khu ẩm thực Corwin là một bổ sung đáng hoan nghênh cho khu phố, và tôi đoán nó sẽ sớm thành một điểm quen thuộc trong bức tranh ẩm thực của thành phố."}], "gl": [{"t": "stood vacant", "ctx": "bị bỏ trống, không ai dùng", "other": "stand: đứng; chịu được (can’t stand)"}, {"t": "boarded up", "ctx": "bị bịt kín bằng ván gỗ", "other": ""}, {"t": "uncertain", "ctx": "chưa rõ, bấp bênh", "other": ""}, {"t": "changed hands", "ctx": "đổi chủ (được bán lại)", "other": "hand in: nộp"}, {"t": "rumors", "ctx": "tin đồn", "other": ""}, {"t": "converted into", "ctx": "được chuyển đổi thành", "other": "convert: quy đổi (tiền, đơn vị)"}, {"t": "luxury apartments", "ctx": "căn hộ cao cấp", "other": ""}, {"t": "turned out to be unfounded", "ctx": "hóa ra là vô căn cứ", "other": "turn out: có mặt, đến dự (turnout: số người tham dự)"}, {"t": "deserve credit", "ctx": "đáng được ghi nhận, đáng khen", "other": "credit: tín dụng; tín chỉ"}, {"t": "preserving", "ctx": "giữ gìn, bảo tồn", "other": "preserve: bảo quản (thực phẩm)"}, {"t": "original character", "ctx": "nét đặc trưng ban đầu", "other": "character: nhân vật; tính cách; ký tự"}, {"t": "exposed timber beams", "ctx": "dầm gỗ để lộ (không ốp trần)", "other": "be exposed to: tiếp xúc với"}, {"t": "arched windows", "ctx": "cửa sổ hình vòm", "other": ""}, {"t": "venues", "ctx": "địa điểm (ăn uống, tổ chức sự kiện)", "other": ""}, {"t": "rarely achieve", "ctx": "hiếm khi đạt được", "other": ""}, {"t": "vendors", "ctx": "người bán hàng", "other": "vendor: nhà cung cấp (cho công ty)"}, {"t": "occupy stalls", "ctx": "thuê, chiếm các gian hàng", "other": "occupied: (phòng, ghế) đang có người"}, {"t": "hand-pulled noodles", "ctx": "mì kéo tay", "other": ""}, {"t": "wood-fired", "ctx": "nướng bằng lò củi", "other": ""}, {"t": "moderate", "ctx": "vừa phải, phải chăng", "other": "moderator: người điều phối thảo luận"}, {"t": "anchor tenant", "ctx": "khách thuê chủ chốt (thu hút khách cho cả khu)", "other": "anchor: cái neo; người dẫn bản tin"}, {"t": "mezzanine", "ctx": "tầng lửng", "other": ""}, {"t": "overlooking", "ctx": "nhìn xuống, hướng ra", "other": "overlook: bỏ sót, không để ý"}, {"t": "acclaimed", "ctx": "được ca ngợi, có tiếng", "other": ""}, {"t": "seasonal tasting menu", "ctx": "thực đơn nếm thử theo mùa", "other": ""}, {"t": "produce", "ctx": "nông sản (rau, củ, quả)", "other": "produce (động từ): sản xuất"}, {"t": "sampled", "ctx": "ăn thử, nếm thử", "other": "sample (danh từ): mẫu thử"}, {"t": "remarkably", "ctx": "đặc biệt, đáng chú ý", "other": ""}, {"t": "A word of caution", "ctx": "một lời cảnh báo nhỏ", "other": ""}, {"t": "booked solid", "ctx": "kín chỗ, hết bàn để đặt", "other": ""}, {"t": "in advance", "ctx": "trước (thời điểm đó)", "other": ""}, {"t": "scarce", "ctx": "khan hiếm", "other": ""}, {"t": "communal tables", "ctx": "bàn dài dùng chung", "other": ""}, {"t": "strike up conversations", "ctx": "bắt chuyện", "other": "strike: đình công; đánh"}, {"t": "fills up", "ctx": "đầy, kín chỗ", "other": "fill out / fill in: điền (đơn)"}, {"t": "better off", "ctx": "tốt hơn là, lợi hơn", "other": ""}, {"t": "minor inconveniences", "ctx": "vài bất tiện nhỏ", "other": ""}, {"t": "a welcome addition", "ctx": "một bổ sung đáng hoan nghênh", "other": ""}, {"t": "suspect", "ctx": "đoán là, ngờ rằng", "other": "suspect (danh từ): nghi phạm"}, {"t": "fixture", "ctx": "nét quen thuộc, thứ luôn có mặt", "other": "fixture: đồ gắn cố định (đèn, bồn rửa)"}, {"t": "dining scene", "ctx": "bức tranh ẩm thực (của thành phố)", "other": ""}], "links": {"drh-foodhall-q1": [["a recently opened venue", "the building finally reopened as the Corwin Food Hall"]], "drh-foodhall-q2": [["unoccupied", "stood vacant"], ["for many years", "For nearly a decade"], ["turned into luxury apartments", "turned out to be unfounded"]], "drh-foodhall-q3": [["main", "anchor tenant"]], "drh-foodhall-q4": [["difficult to get a reservation", "booked solid"], ["difficult to get a reservation", "at least two weeks in advance"]], "drh-foodhall-q5": [["six courses", "seasonal tasting menu"], ["the most memorable", "Its flavor was so remarkably rich"]]}, "lvl": "Khó", "qs": [{"id": "drh-foodhall-q1", "pos": 0, "prompt": "What is the purpose of the blog post?", "options": ["To announce the sale of a historic property", "To review a recently opened venue", "To advertise a job opening at a restaurant", "To criticize a renovation project"], "answer": 1, "explain": "Cả bài kể về Corwin Food Hall vừa mở lại tháng trước (Last month... reopened), người viết đã ghé 3 lần, khen kiến trúc, món ăn và nhắc vài điểm bất tiện: đó là bài nhận xét một địa điểm mới mở. A sai: bài chỉ nói từng đổi chủ, không phải tin rao bán.", "skill": "Mục đích"}, {"id": "drh-foodhall-q2", "pos": 1, "prompt": "What is indicated about the Corwin textile mill?", "options": ["It was unoccupied for many years.", "It was turned into luxury apartments.", "It is owned by Chef Vance.", "It was built last year."], "answer": 0, "explain": "\"For nearly a decade... stood vacant\" = gần 10 năm bỏ trống → unoccupied for many years. B là bẫy: tin đồn biến thành căn hộ \"turned out to be unfounded\" (vô căn cứ).", "skill": "Chi tiết"}, {"id": "drh-foodhall-q3", "pos": 2, "prompt": "In the blog post, the word \"anchor\" in paragraph 3, is closest in meaning to", "options": ["heavy", "main", "fixed", "temporary"], "answer": 1, "explain": "\"anchor tenant\" là khách thuê chủ chốt, quan trọng nhất của cả khu → main. \"fixed\" là nghĩa gần với cái neo (giữ cố định), không hợp ngữ cảnh.", "skill": "Từ đồng nghĩa"}, {"id": "drh-foodhall-q4", "pos": 3, "prompt": "What does the writer suggest about Hollis & Grain?", "options": ["It is difficult to get a reservation there.", "It offers a discount to bus riders.", "It serves only vegetarian dishes.", "It is located on the ground floor."], "answer": 0, "explain": "\"booked solid since its opening night\" + phải đặt trước 2 tuần → khó đặt bàn. D sai: nhà hàng ở mezzanine (tầng lửng), tầng trệt là 22 gian hàng.", "skill": "Suy luận"}, {"id": "drh-foodhall-q5", "pos": 4, "prompt": "In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Of the six courses, the most memorable was a simple roasted squash soup.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 2, "explain": "Câu cần chèn nói về \"six courses\" (các món của thực đơn nếm thử) và một món súp. Ngay trước [3] là \"I sampled it\" (nếm thử thực đơn), ngay sau là \"Its flavor was so remarkably rich\" — \"Its\" chỉ món súp. Nên chèn vào [3].", "skill": "Chèn câu"}]}, {"id": "drh-merger", "set": "drh-merger", "title": "Hãng vận tải mua lại đối thủ", "kind": "Bài báo", "paras": [{"en": "Pellham Logistics to Acquire Rival Carrier", "vi": "Pellham Logistics sẽ mua lại hãng vận tải đối thủ"}, {"en": "DENVER (June 3) — Pellham Logistics announced on Monday that it has reached an agreement to acquire Northline Freight, a regional carrier based in Omaha, for an undisclosed sum. The deal, which still requires approval from federal regulators, is expected to be finalized by the end of the year.", "vi": "DENVER (3/6) — Hôm thứ Hai, Pellham Logistics thông báo đã đạt thỏa thuận mua lại Northline Freight, một hãng vận tải khu vực có trụ sở ở Omaha, với số tiền không công bố. Thương vụ, vẫn cần cơ quan quản lý liên bang phê duyệt, dự kiến hoàn tất trước cuối năm."}, {"en": "The acquisition will add more than 600 trucks to Pellham's fleet and give the company access to Northline's network of distribution centers. Analysts note that Pellham has long had only a limited presence in the northeast, where Northline has cultivated strong relationships with retailers over the past two decades. The company has also struggled to attract large retail clients in the region, many of whom prefer carriers with local warehouses.", "vi": "Thương vụ sẽ bổ sung hơn 600 xe tải vào đội xe của Pellham và cho công ty tiếp cận mạng lưới trung tâm phân phối của Northline. Giới phân tích nhận xét Pellham từ lâu chỉ hiện diện hạn chế ở vùng đông bắc, nơi Northline đã vun đắp quan hệ vững chắc với các nhà bán lẻ suốt hai thập kỷ qua. Công ty cũng chật vật thu hút các khách bán lẻ lớn trong vùng, nhiều người trong số họ thích hãng vận tải có kho hàng tại chỗ."}, {"en": "Industry observers have nonetheless raised concerns about the integration process. The two companies rely on incompatible tracking software, and consolidating their systems could prove both costly and time-consuming. Some customers have also voiced worries that shipping rates could rise once competition in the region decreases. Pellham's chief executive, Marcus Hale, acknowledged the challenge but insisted that a dedicated team had already begun drafting a transition plan.", "vi": "Tuy vậy, giới quan sát trong ngành bày tỏ lo ngại về quá trình hợp nhất. Hai công ty dùng phần mềm theo dõi hàng không tương thích với nhau, và việc gộp hệ thống có thể vừa tốn kém vừa mất thời gian. Một số khách hàng cũng lo giá cước vận chuyển có thể tăng khi cạnh tranh trong vùng giảm đi. Giám đốc điều hành của Pellham, Marcus Hale, thừa nhận khó khăn nhưng khẳng định một nhóm chuyên trách đã bắt đầu soạn kế hoạch chuyển tiếp."}, {"en": "Northline's founder, Priya Desai, will remain with the combined company in an advisory capacity for at least two years. Ms. Desai, who started Northline with just three trucks in 1998, is widely credited with building its reputation for reliability. In a statement, she said that joining Pellham would allow Northline to offer its clients faster delivery times and a broader range of services.", "vi": "Nhà sáng lập Northline, bà Priya Desai, sẽ ở lại công ty sau sáp nhập với vai trò cố vấn ít nhất hai năm. Bà Desai, người khởi nghiệp Northline chỉ với ba xe tải năm 1998, được nhiều người ghi công đã xây nên danh tiếng đáng tin cậy của hãng. Trong một tuyên bố, bà cho biết gia nhập Pellham sẽ giúp Northline mang đến cho khách hàng thời gian giao nhanh hơn và nhiều loại dịch vụ hơn."}, {"en": "Both firms have stressed that no layoffs are planned. Approximately 1,400 Northline positions will be retained, and the Omaha headquarters will continue to operate as a regional office. Mr. Hale added that customers should not expect any disruption to service during the transition.", "vi": "Cả hai công ty đều nhấn mạnh không có kế hoạch cắt giảm nhân sự. Khoảng 1.400 vị trí của Northline sẽ được giữ lại, và trụ sở ở Omaha sẽ tiếp tục hoạt động như một văn phòng khu vực. Ông Hale nói thêm rằng khách hàng sẽ không gặp gián đoạn dịch vụ nào trong giai đoạn chuyển tiếp."}], "gl": [{"t": "Acquire", "ctx": "mua lại (công ty)", "other": "acquire a skill: tiếp thu kỹ năng"}, {"t": "acquire", "ctx": "mua lại (công ty)", "other": "acquire a skill: tiếp thu kỹ năng"}, {"t": "Rival", "ctx": "đối thủ cạnh tranh", "other": ""}, {"t": "Carrier", "ctx": "hãng vận tải", "other": "carrier: hãng bay; nhà mạng điện thoại"}, {"t": "carrier", "ctx": "hãng vận tải", "other": "carrier: hãng bay; nhà mạng điện thoại"}, {"t": "reached an agreement", "ctx": "đạt được thỏa thuận", "other": ""}, {"t": "regional", "ctx": "thuộc khu vực, vùng", "other": ""}, {"t": "undisclosed sum", "ctx": "số tiền không được công bố", "other": ""}, {"t": "requires approval", "ctx": "cần được phê duyệt", "other": ""}, {"t": "federal regulators", "ctx": "cơ quan quản lý liên bang", "other": ""}, {"t": "finalized", "ctx": "hoàn tất, chốt xong", "other": ""}, {"t": "acquisition", "ctx": "thương vụ mua lại", "other": ""}, {"t": "fleet", "ctx": "đội xe (tàu, máy bay) của một công ty", "other": ""}, {"t": "distribution centers", "ctx": "trung tâm phân phối", "other": ""}, {"t": "struggled to attract", "ctx": "chật vật thu hút", "other": ""}, {"t": "warehouses", "ctx": "nhà kho", "other": ""}, {"t": "disruption", "ctx": "sự gián đoạn", "other": ""}, {"t": "Analysts", "ctx": "nhà phân tích", "other": ""}, {"t": "limited presence", "ctx": "hiện diện hạn chế (ít khách, ít thị phần)", "other": "presence: sự có mặt"}, {"t": "cultivated", "ctx": "vun đắp, xây dựng (quan hệ)", "other": "cultivate: trồng trọt"}, {"t": "retailers", "ctx": "nhà bán lẻ", "other": ""}, {"t": "decades", "ctx": "thập kỷ", "other": ""}, {"t": "Industry observers", "ctx": "giới quan sát trong ngành", "other": ""}, {"t": "nonetheless", "ctx": "tuy vậy, dù thế", "other": ""}, {"t": "raised concerns", "ctx": "bày tỏ lo ngại", "other": "raise: tăng (lương); nuôi (con)"}, {"t": "integration", "ctx": "sự hợp nhất (hệ thống, công ty)", "other": ""}, {"t": "incompatible", "ctx": "không tương thích", "other": ""}, {"t": "consolidating", "ctx": "gộp lại, hợp nhất", "other": "consolidate: củng cố"}, {"t": "prove", "ctx": "hóa ra là, tỏ ra là", "other": "prove: chứng minh"}, {"t": "time-consuming", "ctx": "tốn thời gian", "other": ""}, {"t": "voiced worries", "ctx": "bày tỏ lo lắng", "other": ""}, {"t": "shipping rates", "ctx": "giá cước vận chuyển", "other": "rate: tỉ lệ; đánh giá, chấm điểm"}, {"t": "acknowledged", "ctx": "thừa nhận", "other": "acknowledge receipt: xác nhận đã nhận"}, {"t": "insisted", "ctx": "khẳng định, nhất quyết", "other": ""}, {"t": "dedicated team", "ctx": "nhóm chuyên trách", "other": "dedicated: tận tụy"}, {"t": "drafting", "ctx": "soạn thảo (bản nháp)", "other": "draft: bản nháp; gió lùa"}, {"t": "transition plan", "ctx": "kế hoạch chuyển tiếp", "other": ""}, {"t": "advisory capacity", "ctx": "vai trò cố vấn", "other": "capacity: sức chứa; năng lực, công suất"}, {"t": "widely credited with", "ctx": "được nhiều người ghi công vì", "other": ""}, {"t": "reputation for reliability", "ctx": "danh tiếng đáng tin cậy", "other": ""}, {"t": "broader range of", "ctx": "phạm vi rộng hơn, nhiều loại hơn", "other": ""}, {"t": "stressed", "ctx": "nhấn mạnh", "other": "stressed: căng thẳng"}, {"t": "layoffs", "ctx": "đợt cắt giảm nhân sự", "other": ""}, {"t": "positions", "ctx": "vị trí công việc", "other": "position: vị trí, tư thế; quan điểm"}, {"t": "retained", "ctx": "được giữ lại", "other": ""}, {"t": "headquarters", "ctx": "trụ sở chính", "other": ""}], "links": {"drh-merger-q1": [["A merger", "acquire Northline Freight"], ["two transportation companies", "Rival Carrier"]], "drh-merger-q2": [["a region where it has few customers", "a limited presence in the northeast"]], "drh-merger-q3": [["do not work together", "incompatible tracking software"], ["computer systems", "consolidating their systems"]], "drh-merger-q4": [["role", "advisory capacity"]], "drh-merger-q5": [["keep their jobs", "positions will be retained"], ["laid off", "no layoffs are planned"]]}, "lvl": "Khó", "qs": [{"id": "drh-merger-q1", "pos": 0, "prompt": "What is the article mainly about?", "options": ["The opening of a new distribution center", "A merger of two transportation companies", "The retirement of a company founder", "A decrease in shipping rates"], "answer": 1, "explain": "Đoạn 1: Pellham đạt thỏa thuận mua lại Northline Freight, cả hai là hãng vận tải → hợp nhất hai công ty vận tải. C sai: bà Desai vẫn ở lại làm cố vấn.", "skill": "Ý chính"}, {"id": "drh-merger-q2", "pos": 1, "prompt": "According to the article, what will Pellham gain from the deal?", "options": ["A stronger position in a region where it has few customers", "A new tracking software system", "Lower fuel costs", "Its first overseas office"], "answer": 0, "explain": "\"Pellham has long had only a limited presence in the northeast, where Northline has cultivated strong relationships\" → Pellham có thêm chỗ đứng ở vùng mình còn yếu. B là bẫy: phần mềm là vấn đề (không tương thích), không phải lợi ích.", "skill": "Chi tiết"}, {"id": "drh-merger-q3", "pos": 2, "prompt": "What concern have industry observers raised?", "options": ["The deal will not be approved.", "The companies' computer systems do not work together.", "Northline's trucks are outdated.", "Ms. Desai will leave the company."], "answer": 1, "explain": "\"incompatible tracking software\" = phần mềm không tương thích → hệ thống không chạy cùng nhau được.", "skill": "Paraphrase"}, {"id": "drh-merger-q4", "pos": 3, "prompt": "In the article, the word \"capacity\" in paragraph 4, is closest in meaning to", "options": ["ability", "volume", "role", "space"], "answer": 2, "explain": "\"in an advisory capacity\" = với vai trò cố vấn → role. \"volume\", \"space\" là nghĩa sức chứa; \"ability\" là nghĩa năng lực, đều không hợp.", "skill": "Từ đồng nghĩa"}, {"id": "drh-merger-q5", "pos": 4, "prompt": "What is stated about Northline's employees?", "options": ["They will keep their jobs.", "They will move to Denver.", "Some of them will be laid off.", "They will be offered new training."], "answer": 0, "explain": "\"no layoffs are planned\" và \"1,400 Northline positions will be retained\" → nhân viên giữ được việc. B sai: trụ sở Omaha vẫn hoạt động.", "skill": "Chi tiết"}]}, {"id": "drh-fridge", "set": "drh-fridge", "title": "Khiếu nại sửa tủ lạnh", "kind": "E-mail", "paras": [{"en": "To: Customer Care, Altamira Home Appliances | From: Grace Whitfield | Date: February 11 | Subject: Unresolved repair request (Ref. A-20931)", "vi": "Gửi: Bộ phận Chăm sóc khách hàng, Altamira Home Appliances | Từ: Grace Whitfield | Ngày: 11/2 | Tiêu đề: Yêu cầu sửa chữa chưa được giải quyết (Mã A-20931)"}, {"en": "Dear Customer Care Team,", "vi": "Kính gửi Bộ phận Chăm sóc khách hàng,"}, {"en": "I am writing to express my frustration with the way my repair request has been handled. On January 14, I purchased a FrostLine 600 refrigerator from your Elm Avenue showroom. Within a week, the built-in water dispenser stopped working, and water began leaking onto the kitchen floor whenever the door was opened. I have had to place towels around the unit and empty a tray every few hours.", "vi": "Tôi viết thư này để bày tỏ sự bực bội về cách yêu cầu sửa chữa của tôi được xử lý. Ngày 14/1, tôi mua một tủ lạnh FrostLine 600 tại phòng trưng bày trên đại lộ Elm. Chưa đầy một tuần, vòi lấy nước gắn liền ngừng hoạt động, và nước bắt đầu rò ra sàn bếp mỗi lần mở cửa tủ. Tôi phải đặt khăn quanh tủ và đổ khay nước vài tiếng một lần."}, {"en": "I reported the defect on January 21, and a technician inspected the appliance two days later. He confirmed that the dispenser valve was faulty and assured me that a replacement part would be ordered immediately. Since then, however, I have received no follow-up whatsoever. When I called your service line last week, I was put on hold for more than thirty minutes before the call was disconnected. This was particularly frustrating because I had already taken a day off work to be home for the technician’s visit.", "vi": "Tôi báo lỗi ngày 21/1, và hai ngày sau một kỹ thuật viên đến kiểm tra. Anh ấy xác nhận van của vòi nước bị hỏng và cam đoan sẽ đặt linh kiện thay thế ngay. Thế nhưng từ đó đến nay tôi không nhận được bất kỳ liên lạc nào. Tuần trước tôi gọi đường dây dịch vụ thì bị bắt chờ máy hơn ba mươi phút rồi cuộc gọi bị ngắt. Điều này càng bực mình vì tôi đã phải nghỉ làm một ngày để ở nhà chờ kỹ thuật viên đến."}, {"en": "I would also like to point out that I paid an additional $150 for your Premium Installation package, which, according to your brochure, guarantees that any defect discovered within the first month will be repaired within ten business days. That commitment has clearly not been honored.", "vi": "Tôi cũng muốn lưu ý rằng tôi đã trả thêm 150 đô cho gói Lắp đặt Cao cấp của quý công ty, mà theo tờ giới thiệu thì đảm bảo mọi lỗi phát hiện trong tháng đầu sẽ được sửa trong vòng mười ngày làm việc. Rõ ràng cam kết đó đã không được thực hiện."}, {"en": "Given these circumstances, I believe a partial refund of the installation fee is warranted. I would also appreciate it if someone could contact me by Friday to schedule the repair. I have been a loyal customer of Altamira for many years and would prefer to resolve this matter without escalating it further. Please note that I have kept copies of my receipt and all related correspondence.", "vi": "Xét tình hình này, tôi cho rằng việc hoàn lại một phần phí lắp đặt là hợp lý. Tôi cũng sẽ rất cảm kích nếu có người liên hệ với tôi trước thứ Sáu để hẹn lịch sửa. Tôi là khách hàng thân thiết của Altamira nhiều năm và muốn giải quyết việc này mà không phải khiếu nại lên cao hơn. Xin lưu ý tôi vẫn giữ bản sao hóa đơn và mọi thư từ liên quan."}, {"en": "Sincerely, Grace Whitfield", "vi": "Trân trọng, Grace Whitfield"}], "gl": [{"t": "Unresolved", "ctx": "chưa được giải quyết", "other": ""}, {"t": "express my frustration", "ctx": "bày tỏ sự bực bội", "other": ""}, {"t": "handled", "ctx": "được xử lý", "other": "handle (danh từ): tay cầm"}, {"t": "showroom", "ctx": "phòng trưng bày", "other": ""}, {"t": "built-in", "ctx": "gắn liền, lắp sẵn", "other": ""}, {"t": "water dispenser", "ctx": "vòi lấy nước", "other": ""}, {"t": "leaking", "ctx": "rò rỉ", "other": "leak: làm lộ (thông tin)"}, {"t": "defect", "ctx": "lỗi, khiếm khuyết (sản phẩm)", "other": ""}, {"t": "technician", "ctx": "kỹ thuật viên", "other": ""}, {"t": "inspected", "ctx": "kiểm tra kỹ", "other": "inspector: thanh tra viên"}, {"t": "appliance", "ctx": "thiết bị gia dụng", "other": "application: đơn xin; ứng dụng"}, {"t": "valve", "ctx": "van", "other": ""}, {"t": "faulty", "ctx": "bị lỗi, hỏng", "other": ""}, {"t": "assured", "ctx": "cam đoan, trấn an", "other": "insured: được bảo hiểm"}, {"t": "replacement part", "ctx": "linh kiện thay thế", "other": ""}, {"t": "follow-up", "ctx": "liên lạc tiếp theo, phản hồi lại", "other": ""}, {"t": "whatsoever", "ctx": "gì cả, chút nào (nhấn mạnh phủ định)", "other": ""}, {"t": "put on hold", "ctx": "bị bắt chờ máy", "other": "on hold: tạm hoãn (dự án)"}, {"t": "disconnected", "ctx": "bị ngắt (cuộc gọi, kết nối)", "other": ""}, {"t": "point out", "ctx": "chỉ ra, lưu ý", "other": ""}, {"t": "package", "ctx": "gói dịch vụ", "other": "package: bưu kiện"}, {"t": "brochure", "ctx": "tờ giới thiệu, sách quảng cáo", "other": ""}, {"t": "guarantees", "ctx": "đảm bảo, cam kết", "other": ""}, {"t": "business days", "ctx": "ngày làm việc (trừ cuối tuần, lễ)", "other": ""}, {"t": "commitment", "ctx": "cam kết", "other": "commitment: sự tận tâm"}, {"t": "honored", "ctx": "được thực hiện (lời hứa, cam kết)", "other": "honor: vinh dự; tôn vinh"}, {"t": "Given these circumstances", "ctx": "xét tình hình này", "other": ""}, {"t": "partial refund", "ctx": "hoàn tiền một phần", "other": ""}, {"t": "warranted", "ctx": "hợp lý, chính đáng", "other": "warranty: bảo hành"}, {"t": "I would also appreciate it if", "ctx": "tôi cũng sẽ rất cảm kích nếu", "other": ""}, {"t": "loyal customer", "ctx": "khách hàng thân thiết", "other": ""}, {"t": "resolve this matter", "ctx": "giải quyết việc này", "other": "matter (động từ): quan trọng (it doesn’t matter)"}, {"t": "unit", "ctx": "cái máy, thiết bị (ở đây là chiếc tủ)", "other": "unit: căn hộ; đơn vị"}, {"t": "tray", "ctx": "khay", "other": ""}, {"t": "particularly", "ctx": "đặc biệt là", "other": ""}, {"t": "taken a day off", "ctx": "nghỉ một ngày", "other": ""}, {"t": "correspondence", "ctx": "thư từ trao đổi", "other": ""}, {"t": "escalating", "ctx": "đẩy (khiếu nại) lên cấp cao hơn", "other": "escalate: leo thang"}], "links": {"drh-fridge-q1": [["complain", "express my frustration"], ["a delayed repair", "I have received no follow-up whatsoever"]], "drh-fridge-q2": [["did not function properly", "stopped working"], ["One of its parts", "the dispenser valve was faulty"]], "drh-fridge-q3": [["waited a long time", "put on hold for more than thirty minutes"], ["without speaking to anyone", "the call was disconnected"]], "drh-fridge-q4": [["Partial reimbursement", "a partial refund"], ["a service fee", "the installation fee"]], "drh-fridge-q5": [["fulfilled", "honored"]]}, "lvl": "Khó", "qs": [{"id": "drh-fridge-q1", "pos": 0, "prompt": "Why did Ms. Whitfield write the e-mail?", "options": ["To request a replacement refrigerator", "To complain about a delayed repair", "To cancel an installation appointment", "To praise a technician"], "answer": 1, "explain": "Mở đầu: \"express my frustration with the way my repair request has been handled\", sau đó kể đã báo lỗi từ 21/1 mà không ai liên lạc lại → phàn nàn việc sửa bị chậm. A sai: bà muốn sửa và hoàn một phần phí, không đòi đổi tủ.", "skill": "Mục đích"}, {"id": "drh-fridge-q2", "pos": 1, "prompt": "What problem did Ms. Whitfield have with her refrigerator?", "options": ["It was delivered to the wrong address.", "One of its parts did not function properly.", "It was too large for her kitchen.", "It made a loud noise."], "answer": 1, "explain": "Vòi nước \"stopped working\" và \"the dispenser valve was faulty\" → một bộ phận không hoạt động đúng.", "skill": "Paraphrase"}, {"id": "drh-fridge-q3", "pos": 2, "prompt": "What is indicated about Ms. Whitfield's phone call?", "options": ["She waited a long time without speaking to anyone.", "She was told that the part had arrived.", "She spoke with the technician.", "She was offered a refund."], "answer": 0, "explain": "\"put on hold for more than thirty minutes before the call was disconnected\" → chờ rất lâu rồi bị ngắt, không nói chuyện được với ai.", "skill": "Chi tiết"}, {"id": "drh-fridge-q4", "pos": 3, "prompt": "What does Ms. Whitfield ask for?", "options": ["A full refund for the refrigerator", "Partial reimbursement of a service fee", "A free extended warranty", "A visit from a store manager"], "answer": 1, "explain": "\"a partial refund of the installation fee is warranted\" → hoàn lại một phần phí dịch vụ (lắp đặt). A là bẫy: bà chỉ đòi một phần phí lắp đặt, không phải tiền tủ.", "skill": "Paraphrase"}, {"id": "drh-fridge-q5", "pos": 4, "prompt": "In the e-mail, the word \"honored\" in paragraph 3, is closest in meaning to", "options": ["respected", "fulfilled", "awarded", "celebrated"], "answer": 1, "explain": "\"That commitment has clearly not been honored\" = cam kết không được thực hiện → fulfilled. \"respected\", \"awarded\" là nghĩa honor = tôn trọng, vinh danh, không hợp ở đây.", "skill": "Từ đồng nghĩa"}]}, {"id": "drh-summit", "set": "drh-summit", "title": "Đăng ký hội nghị bao bì xanh", "kind": "Trang web", "paras": [{"en": "Midwest Sustainable Packaging Summit | Registration Information", "vi": "Hội nghị Bao bì Bền vững vùng Trung Tây | Thông tin đăng ký"}, {"en": "The fourth annual Midwest Sustainable Packaging Summit will be held at the Larkspur Convention Center in Columbus from September 22 to 24. The summit brings together manufacturers, designers, and supply chain managers who are committed to reducing waste without compromising product safety or shelf life. This year's sessions will focus on compostable materials, refillable containers, and recent changes to labeling regulations.", "vi": "Hội nghị Bao bì Bền vững vùng Trung Tây thường niên lần thứ tư sẽ diễn ra tại Trung tâm Hội nghị Larkspur ở Columbus từ ngày 22 đến 24/9. Hội nghị quy tụ các nhà sản xuất, nhà thiết kế và quản lý chuỗi cung ứng cam kết giảm rác thải mà không làm ảnh hưởng đến an toàn sản phẩm hay hạn sử dụng. Các phiên năm nay tập trung vào vật liệu phân hủy được, hộp đựng dùng lại được và các thay đổi gần đây về quy định ghi nhãn."}, {"en": "Registration options: A full-access pass ($420) covers admission to all sessions, workshops, and exhibition halls, as well as the networking reception on the evening of September 23. A single-day pass ($175) provides entry to all sessions on the selected day but does not include the reception. A limited number of student passes ($90), which include all sessions but not the reception, are available to those enrolled full-time in a related degree program. Proof of enrollment is required, and only 60 such passes will be issued.", "vi": "Các loại vé: Vé trọn gói (420 đô) bao gồm vào cửa tất cả các phiên, hội thảo và sảnh triển lãm, cùng tiệc giao lưu tối 23/9. Vé một ngày (175 đô) cho vào tất cả các phiên trong ngày đã chọn nhưng không gồm tiệc. Một số lượng giới hạn vé sinh viên (90 đô), gồm tất cả các phiên nhưng không gồm tiệc, dành cho người đang học toàn thời gian một chương trình liên quan. Cần có giấy xác nhận đang theo học, và chỉ phát hành 60 vé loại này."}, {"en": "Participants who register before August 15 are eligible for a 15 percent early-bird discount on full-access and single-day passes. Group discounts are available for organizations registering five or more employees. Discount codes cannot be combined with other offers.", "vi": "Người đăng ký trước 15/8 được giảm 15% (ưu đãi đăng ký sớm) cho vé trọn gói và vé một ngày. Có giảm giá theo nhóm cho tổ chức đăng ký từ năm nhân viên trở lên. Không được dùng mã giảm giá cùng với ưu đãi khác."}, {"en": "Cancellations: Registrants who cancel on or before September 1 will receive a full refund minus a $25 processing fee. After that date, refunds will not be issued; however, passes may be transferred to a colleague, provided that the organizers are notified at least 48 hours before the event begins.", "vi": "Hủy đăng ký: Người hủy trong hoặc trước ngày 1/9 được hoàn toàn bộ tiền trừ 25 đô phí xử lý. Sau ngày đó sẽ không hoàn tiền; tuy nhiên có thể chuyển vé cho đồng nghiệp, với điều kiện báo cho ban tổ chức ít nhất 48 giờ trước khi sự kiện bắt đầu."}, {"en": "Accommodations: A block of rooms has been reserved at the Hotel Wren, which is connected to the convention center by a covered walkway. To secure the discounted rate of $139 per night, guests should book by August 30 or until the block sells out, whichever comes first. Shuttle service from the airport is not provided, but taxis are readily available.", "vi": "Chỗ ở: Một lượng phòng đã được giữ sẵn tại khách sạn Wren, nối với trung tâm hội nghị bằng lối đi có mái che. Để có giá ưu đãi 139 đô/đêm, khách nên đặt trước 30/8 hoặc trước khi hết phòng giữ sẵn, tùy điều kiện nào đến trước. Không có xe đưa đón từ sân bay, nhưng taxi luôn sẵn."}], "gl": [{"t": "Sustainable", "ctx": "bền vững (thân thiện môi trường)", "other": ""}, {"t": "Summit", "ctx": "hội nghị lớn", "other": "summit: đỉnh núi; hội nghị thượng đỉnh"}, {"t": "summit", "ctx": "hội nghị lớn", "other": "summit: đỉnh núi; hội nghị thượng đỉnh"}, {"t": "Registration", "ctx": "sự đăng ký", "other": ""}, {"t": "annual", "ctx": "thường niên, hằng năm", "other": ""}, {"t": "brings together", "ctx": "quy tụ, tập hợp", "other": ""}, {"t": "manufacturers", "ctx": "nhà sản xuất", "other": ""}, {"t": "supply chain", "ctx": "chuỗi cung ứng", "other": ""}, {"t": "committed to", "ctx": "cam kết, tận tâm với", "other": ""}, {"t": "reducing waste", "ctx": "giảm rác thải, giảm lãng phí", "other": ""}, {"t": "compromising", "ctx": "làm ảnh hưởng xấu đến, đánh đổi", "other": "compromise: thỏa hiệp"}, {"t": "shelf life", "ctx": "hạn sử dụng (thời gian bảo quản được)", "other": ""}, {"t": "compostable", "ctx": "ủ thành phân được, tự phân hủy", "other": ""}, {"t": "refillable containers", "ctx": "hộp, chai đổ đầy lại được", "other": ""}, {"t": "labeling regulations", "ctx": "quy định ghi nhãn", "other": ""}, {"t": "covers admission", "ctx": "bao gồm vé vào cửa", "other": "cover: che; đưa tin; chi trả (chi phí)"}, {"t": "exhibition halls", "ctx": "sảnh triển lãm", "other": ""}, {"t": "networking reception", "ctx": "tiệc giao lưu kết nối", "other": "reception: quầy lễ tân; sóng (điện thoại)"}, {"t": "provides entry", "ctx": "cho phép vào", "other": ""}, {"t": "enrolled full-time", "ctx": "đang học toàn thời gian", "other": ""}, {"t": "degree program", "ctx": "chương trình học lấy bằng", "other": ""}, {"t": "Proof of enrollment", "ctx": "giấy xác nhận đang theo học", "other": ""}, {"t": "issued", "ctx": "được phát hành, cấp", "other": "issue (danh từ): vấn đề; số (tạp chí)"}, {"t": "eligible for", "ctx": "đủ điều kiện hưởng", "other": ""}, {"t": "early-bird discount", "ctx": "giảm giá đăng ký sớm", "other": ""}, {"t": "Registrants", "ctx": "người đã đăng ký", "other": ""}, {"t": "processing fee", "ctx": "phí xử lý", "other": ""}, {"t": "transferred", "ctx": "được chuyển nhượng", "other": "transfer: chuyển (tiền, công tác, chuyến bay)"}, {"t": "provided that", "ctx": "với điều kiện là", "other": ""}, {"t": "notified", "ctx": "được thông báo", "other": ""}, {"t": "Accommodations", "ctx": "chỗ ở (khách sạn)", "other": ""}, {"t": "A block of rooms", "ctx": "một lượng phòng giữ sẵn cho đoàn", "other": "block: dãy nhà; chặn"}, {"t": "covered walkway", "ctx": "lối đi có mái che", "other": ""}, {"t": "secure", "ctx": "có được, giành được", "other": "secure (tính từ): an toàn, chắc chắn"}, {"t": "combined with", "ctx": "dùng chung với, gộp với", "other": ""}, {"t": "Shuttle service", "ctx": "dịch vụ xe đưa đón", "other": ""}, {"t": "readily available", "ctx": "luôn có sẵn, dễ tìm", "other": ""}, {"t": "sells out", "ctx": "bán hết", "other": ""}, {"t": "whichever comes first", "ctx": "tùy điều kiện nào đến trước", "other": ""}], "links": {"drh-summit-q1": [["Professionals in the packaging industry", "manufacturers, designers, and supply chain managers"]], "drh-summit-q2": [["the evening event", "the networking reception on the evening of September 23"], ["The full-access pass", "A full-access pass ($420)"]], "drh-summit-q3": [["Their number is limited", "only 60 such passes will be issued"], ["early-bird discount", "early-bird discount on full-access and single-day passes"]], "drh-summit-q4": [["give the pass to a coworker", "passes may be transferred to a colleague"], ["under certain conditions", "provided that the organizers are notified"], ["a refund minus $25", "refunds will not be issued"]], "drh-summit-q5": [["obtain", "secure the discounted rate"]]}, "lvl": "Khó", "qs": [{"id": "drh-summit-q1", "pos": 0, "prompt": "For whom is the summit most likely intended?", "options": ["Professionals in the packaging industry", "Hotel managers", "Food critics", "Real estate agents"], "answer": 0, "explain": "\"brings together manufacturers, designers, and supply chain managers\" làm về bao bì → người làm trong ngành bao bì.", "skill": "Suy luận"}, {"id": "drh-summit-q2", "pos": 1, "prompt": "Which pass includes admission to the evening event?", "options": ["The full-access pass", "The single-day pass", "The student pass", "All passes"], "answer": 0, "explain": "Chỉ vé trọn gói có \"the networking reception on the evening of September 23\". Vé một ngày và vé sinh viên đều ghi rõ không gồm tiệc.", "skill": "Chi tiết"}, {"id": "drh-summit-q3", "pos": 2, "prompt": "What is indicated about student passes?", "options": ["Their number is limited.", "They can be purchased only on site.", "They include a hotel room.", "They are eligible for the early-bird discount."], "answer": 0, "explain": "\"A limited number of student passes\" và \"only 60 such passes will be issued\" → số lượng có hạn. D sai: giảm giá sớm chỉ áp dụng cho vé trọn gói và vé một ngày.", "skill": "Chi tiết"}, {"id": "drh-summit-q4", "pos": 3, "prompt": "What is true about a participant who cancels on September 5?", "options": ["The participant will receive a refund minus $25.", "The participant can give the pass to a coworker under certain conditions.", "The participant must pay an additional fee.", "The participant can attend only one day of the event."], "answer": 1, "explain": "Sau 1/9 không hoàn tiền (A sai), nhưng \"passes may be transferred to a colleague, provided that the organizers are notified at least 48 hours before\" → chuyển vé cho đồng nghiệp nếu báo trước.", "skill": "Suy luận"}, {"id": "drh-summit-q5", "pos": 4, "prompt": "On the web page, the word \"secure\" in paragraph 5, is closest in meaning to", "options": ["protect", "lock", "obtain", "calm"], "answer": 2, "explain": "\"To secure the discounted rate\" = để có được giá ưu đãi → obtain. \"protect\", \"lock\" là nghĩa bảo vệ, khóa chặt.", "skill": "Từ đồng nghĩa"}]}, {"id": "drh-travel", "set": "drh-travel", "title": "Quy định mới về công tác phí", "kind": "Memo", "paras": [{"en": "MEMO | To: All Employees | From: Helena Brandt, Director of Finance | Date: October 28 | Re: Revised travel and expense procedures", "vi": "GHI NHỚ | Gửi: Toàn thể nhân viên | Từ: Helena Brandt, Giám đốc Tài chính | Ngày: 28/10 | V/v: Quy trình công tác và thanh toán chi phí sửa đổi"}, {"en": "Following a comprehensive review of last year's spending, during which travel costs exceeded budgeted amounts in nearly every department, the finance team has revised the company's travel and expense procedures. The changes described below take effect on December 1 and apply to all domestic and international business trips.", "vi": "Sau đợt rà soát toàn diện chi tiêu năm ngoái, khi chi phí đi lại vượt ngân sách dự kiến ở gần như mọi phòng ban, bộ phận tài chính đã sửa đổi quy trình công tác và thanh toán chi phí của công ty. Các thay đổi dưới đây có hiệu lực từ 1/12 và áp dụng cho mọi chuyến công tác trong nước và quốc tế."}, {"en": "First, all trips must now be approved by both the employee's direct supervisor and the finance department at least ten business days before departure. Requests submitted after this deadline will be considered only in urgent cases and must be justified in writing. Approval requests can be submitted through the online travel portal.", "vi": "Thứ nhất, mọi chuyến đi từ nay phải được cả quản lý trực tiếp của nhân viên lẫn phòng tài chính phê duyệt ít nhất mười ngày làm việc trước khi khởi hành. Yêu cầu nộp sau hạn này chỉ được xem xét trong trường hợp khẩn cấp và phải giải trình bằng văn bản. Có thể gửi yêu cầu phê duyệt qua cổng đặt công tác trực tuyến."}, {"en": "Second, for flights longer than six hours, business-class seats may be booked with prior approval. For shorter flights, employees must book economy-class tickets, and upgrades will be permitted only for documented medical reasons. Employees who wish to upgrade at their own expense remain free to do so.", "vi": "Thứ hai, với chuyến bay dài hơn sáu tiếng, có thể đặt ghế hạng thương gia nếu được duyệt trước. Với chuyến ngắn hơn, nhân viên phải đặt vé hạng phổ thông, và chỉ được nâng hạng vì lý do sức khỏe có giấy tờ chứng minh. Nhân viên muốn tự trả tiền nâng hạng thì vẫn được tự do làm vậy."}, {"en": "Third, the daily meal allowance has been set at $60 for domestic travel and $85 for international travel. Itemized receipts must be attached to every claim; credit card statements alone will no longer be accepted. All expense claims must be filed within 30 days of the employee's return, and claims submitted after this period may not be reimbursed. Alcohol purchases are not eligible for reimbursement under any circumstances.", "vi": "Thứ ba, phụ cấp ăn uống mỗi ngày là 60 đô cho công tác trong nước và 85 đô cho công tác quốc tế. Mọi yêu cầu thanh toán phải kèm hóa đơn ghi chi tiết; chỉ có sao kê thẻ tín dụng sẽ không còn được chấp nhận. Mọi yêu cầu thanh toán chi phí phải nộp trong vòng 30 ngày sau khi về, nộp muộn hơn có thể không được hoàn tiền. Tiền mua đồ uống có cồn không được hoàn trong bất kỳ trường hợp nào."}, {"en": "To ease the transition, the finance team will hold two information sessions, on November 18 and November 20. Both sessions will cover identical content, so employees need to attend only one. Attendance is optional, and a recording will be posted on the company intranet for those unable to attend. Questions may be directed to Carl Ostrowski in the finance office at extension 4417.", "vi": "Để việc chuyển đổi suôn sẻ, bộ phận tài chính sẽ tổ chức hai buổi giới thiệu vào 18/11 và 20/11. Hai buổi có nội dung giống hệt nhau nên nhân viên chỉ cần dự một buổi. Không bắt buộc tham dự, và bản ghi sẽ được đăng trên mạng nội bộ cho ai không dự được. Câu hỏi xin gửi tới Carl Ostrowski ở phòng tài chính, số máy lẻ 4417."}], "gl": [{"t": "Revised", "ctx": "được sửa đổi", "other": ""}, {"t": "revised", "ctx": "đã sửa đổi", "other": ""}, {"t": "expense", "ctx": "chi phí", "other": "expensive: đắt"}, {"t": "procedures", "ctx": "quy trình, thủ tục", "other": ""}, {"t": "comprehensive review", "ctx": "đợt rà soát toàn diện", "other": ""}, {"t": "exceeded budgeted amounts", "ctx": "vượt mức ngân sách dự kiến", "other": ""}, {"t": "take effect", "ctx": "có hiệu lực", "other": ""}, {"t": "domestic", "ctx": "trong nước", "other": "domestic: (thuộc) gia đình, việc nhà"}, {"t": "direct supervisor", "ctx": "quản lý trực tiếp", "other": ""}, {"t": "departure", "ctx": "sự khởi hành", "other": ""}, {"t": "urgent cases", "ctx": "trường hợp khẩn cấp", "other": ""}, {"t": "justified in writing", "ctx": "giải trình bằng văn bản", "other": ""}, {"t": "prior approval", "ctx": "sự phê duyệt trước", "other": ""}, {"t": "economy-class", "ctx": "hạng phổ thông", "other": ""}, {"t": "upgrades", "ctx": "việc nâng hạng (vé, phòng)", "other": "upgrade: nâng cấp (phần mềm, máy)"}, {"t": "permitted", "ctx": "được cho phép", "other": "permit (danh từ): giấy phép"}, {"t": "documented medical reasons", "ctx": "lý do sức khỏe có giấy tờ chứng minh", "other": ""}, {"t": "at their own expense", "ctx": "tự chi trả", "other": ""}, {"t": "remain free to", "ctx": "vẫn được tự do", "other": ""}, {"t": "meal allowance", "ctx": "phụ cấp ăn uống", "other": "allowance: tiền tiêu vặt; mức cho phép (hành lý)"}, {"t": "Itemized receipts", "ctx": "hóa đơn ghi chi tiết từng món", "other": ""}, {"t": "claim", "ctx": "yêu cầu thanh toán (chi phí)", "other": "claim: khẳng định; nhận lại (hành lý)"}, {"t": "expense claims", "ctx": "yêu cầu thanh toán chi phí", "other": ""}, {"t": "credit card statements", "ctx": "sao kê thẻ tín dụng", "other": "statement: lời tuyên bố"}, {"t": "filed", "ctx": "nộp (hồ sơ)", "other": "file: tập tin; xếp vào hồ sơ"}, {"t": "portal", "ctx": "cổng (trang web nội bộ)", "other": ""}, {"t": "under any circumstances", "ctx": "trong bất kỳ trường hợp nào", "other": ""}, {"t": "reimbursed", "ctx": "được hoàn trả (chi phí)", "other": ""}, {"t": "ease the transition", "ctx": "giúp việc chuyển đổi suôn sẻ", "other": "ease: giảm bớt (đau); with ease: dễ dàng"}, {"t": "identical content", "ctx": "nội dung giống hệt", "other": ""}, {"t": "Attendance", "ctx": "việc tham dự", "other": ""}, {"t": "optional", "ctx": "không bắt buộc", "other": ""}, {"t": "intranet", "ctx": "mạng nội bộ công ty", "other": ""}, {"t": "directed to", "ctx": "gửi tới, chuyển tới", "other": "director: giám đốc; đạo diễn"}, {"t": "extension", "ctx": "số máy lẻ", "other": "extension: sự gia hạn; phần mở rộng"}], "links": {"drh-travel-q1": [["changes to company policies", "revised the company's travel and expense procedures"]], "drh-travel-q2": [["Get permission from two parties", "approved by both the employee's direct supervisor and the finance department"]], "drh-travel-q3": [["a five-hour flight", "For shorter flights"], ["a documented health condition", "documented medical reasons"]], "drh-travel-q4": [["the same material", "identical content"], ["Attendance is required", "Attendance is optional"]], "drh-travel-q5": [["facilitate", "ease the transition"]]}, "lvl": "Khó", "qs": [{"id": "drh-travel-q1", "pos": 0, "prompt": "What is the purpose of the memo?", "options": ["To explain changes to company policies", "To announce cuts to department budgets", "To introduce a new finance director", "To invite employees to a conference"], "answer": 0, "explain": "\"the finance team has revised the company's travel and expense procedures. The changes described below...\" → giải thích thay đổi quy định. B là bẫy: chi phí vượt ngân sách là lý do, không phải thông báo cắt ngân sách.", "skill": "Mục đích"}, {"id": "drh-travel-q2", "pos": 1, "prompt": "What must employees do before taking a business trip?", "options": ["Get permission from two parties", "Book business-class tickets", "Attend an information session", "Submit their receipts"], "answer": 0, "explain": "\"approved by both the employee's direct supervisor and the finance department\" → cần hai bên đồng ý. C sai: buổi giới thiệu không bắt buộc.", "skill": "Paraphrase"}, {"id": "drh-travel-q3", "pos": 2, "prompt": "According to the memo, when may an employee upgrade a five-hour flight at the company's expense?", "options": ["When the employee is traveling internationally", "When the employee has a documented health condition", "When the trip is booked ten days in advance", "When the employee returns within 30 days"], "answer": 1, "explain": "Chuyến 5 tiếng là \"shorter flights\" (dưới 6 tiếng) → chỉ được nâng hạng vì \"documented medical reasons\" = vấn đề sức khỏe có giấy tờ.", "skill": "Suy luận"}, {"id": "drh-travel-q4", "pos": 3, "prompt": "What is indicated about the information sessions?", "options": ["Both sessions will present the same material.", "Attendance is required.", "They will be held in December.", "They will not be recorded."], "answer": 0, "explain": "\"Both sessions will cover identical content\" → cùng nội dung. B sai: \"Attendance is optional\"; D sai: có bản ghi trên intranet.", "skill": "Chi tiết"}, {"id": "drh-travel-q5", "pos": 4, "prompt": "In the memo, the word \"ease\" in paragraph 5, is closest in meaning to", "options": ["comfort", "facilitate", "lessen", "loosen"], "answer": 1, "explain": "\"To ease the transition\" = giúp việc chuyển đổi dễ dàng → facilitate. \"lessen\" hợp với \"ease the pain\" (giảm đau), không hợp với \"transition\".", "skill": "Từ đồng nghĩa"}]}, {"id": "drh-theater", "set": "drh-theater", "title": "Gây quỹ trùng tu nhà hát", "kind": "Thông cáo báo chí", "paras": [{"en": "FOR IMMEDIATE RELEASE | Contact: Dana Okafor, Development Director, Riverbend Community Theater", "vi": "ĐĂNG NGAY | Liên hệ: Dana Okafor, Giám đốc Phát triển, Nhà hát Cộng đồng Riverbend"}, {"en": "Riverbend Community Theater Launches Restoration Campaign", "vi": "Nhà hát Cộng đồng Riverbend khởi động chiến dịch trùng tu"}, {"en": "RIVERBEND (March 9) — The Riverbend Community Theater today announced a $2.4 million campaign to restore the Alcott Playhouse, the 1920s venue that has been its home for more than forty years. Theater officials say decades of deferred maintenance have taken a toll on the building, which now suffers from a leaking roof, frequent heating malfunctions, and seating that is not accessible to patrons who use wheelchairs.", "vi": "RIVERBEND (9/3) — Hôm nay Nhà hát Cộng đồng Riverbend công bố chiến dịch 2,4 triệu đô để trùng tu Nhà hát Alcott, công trình từ thập niên 1920 đã là nơi hoạt động của nhà hát hơn bốn mươi năm. Ban quản lý nhà hát cho biết hàng chục năm trì hoãn bảo trì đã làm tòa nhà xuống cấp, giờ mái thì dột, hệ thống sưởi thường xuyên trục trặc, và ghế ngồi không phù hợp cho khán giả dùng xe lăn."}, {"en": "The need for repairs became impossible to ignore last winter, when a burst pipe flooded the backstage area and forced the theater to relocate two productions to a nearby high school auditorium. “Our audiences were remarkably patient,” said artistic director Leon Marchetti, “but we cannot keep asking them to accept these conditions.” Several longtime subscribers also complained that the auditorium was uncomfortably cold during evening performances.", "vi": "Nhu cầu sửa chữa trở nên không thể làm ngơ vào mùa đông năm ngoái, khi một ống nước vỡ làm ngập khu hậu trường và buộc nhà hát chuyển hai vở diễn sang hội trường của một trường trung học gần đó. “Khán giả của chúng tôi kiên nhẫn đáng nể,” giám đốc nghệ thuật Leon Marchetti nói, “nhưng chúng tôi không thể cứ bắt họ chấp nhận điều kiện như thế này mãi.” Một số khán giả mua vé dài hạn lâu năm cũng phàn nàn khán phòng lạnh khó chịu trong các suất diễn buổi tối."}, {"en": "The renovation will replace the roof and heating system, install a ramp and an elevator, and add 40 accessible seats. Architects have also pledged to retain the building's most distinctive features, including its ornate plaster ceiling and the illuminated marquee that has greeted theatergoers on Main Street since 1927. The lobby will also be expanded to reduce crowding during intermissions.", "vi": "Đợt cải tạo sẽ thay mái và hệ thống sưởi, lắp đường dốc và thang máy, thêm 40 ghế cho người khuyết tật. Các kiến trúc sư cũng cam kết giữ lại những nét đặc trưng nhất của tòa nhà, gồm trần thạch cao trang trí cầu kỳ và biển hiệu đèn trước rạp đã chào đón khán giả trên phố Main từ năm 1927. Sảnh cũng sẽ được mở rộng để bớt chen chúc lúc giải lao."}, {"en": "Thanks to early supporters, more than $900,000 has already been pledged. In addition, the Lindqvist Foundation has agreed to match every individual donation, dollar for dollar, up to a total of $500,000. Donors who contribute $1,000 or more will have their names engraved on a commemorative wall in the renovated lobby. Construction is scheduled to begin once 75 percent of the goal has been raised, a milestone organizers hope to reach by the end of the summer.", "vi": "Nhờ những người ủng hộ đầu tiên, hơn 900.000 đô đã được cam kết đóng góp. Ngoài ra, Quỹ Lindqvist đồng ý góp thêm đúng bằng mỗi khoản quyên góp cá nhân, một đô đổi một đô, tối đa tổng cộng 500.000 đô. Người đóng góp từ 1.000 đô trở lên sẽ được khắc tên lên bức tường ghi danh ở sảnh sau cải tạo. Việc thi công dự kiến bắt đầu khi quyên được 75% mục tiêu, cột mốc mà ban tổ chức hy vọng đạt được trước cuối hè."}], "gl": [{"t": "FOR IMMEDIATE RELEASE", "ctx": "đăng ngay (dòng đầu của thông cáo báo chí)", "other": ""}, {"t": "Development Director", "ctx": "giám đốc phát triển (lo gây quỹ)", "other": ""}, {"t": "Launches", "ctx": "khởi động, ra mắt", "other": "launch: phóng (tên lửa); hạ thủy (tàu)"}, {"t": "Restoration Campaign", "ctx": "chiến dịch trùng tu", "other": ""}, {"t": "restore", "ctx": "trùng tu, khôi phục", "other": ""}, {"t": "venue", "ctx": "địa điểm (biểu diễn, tổ chức sự kiện)", "other": ""}, {"t": "officials", "ctx": "người phụ trách, quan chức", "other": ""}, {"t": "deferred maintenance", "ctx": "việc bảo trì bị trì hoãn", "other": ""}, {"t": "have taken a toll on", "ctx": "đã gây tổn hại cho", "other": "toll: phí cầu đường"}, {"t": "suffers from", "ctx": "gặp phải, chịu (vấn đề)", "other": ""}, {"t": "leaking roof", "ctx": "mái dột", "other": ""}, {"t": "malfunctions", "ctx": "sự cố, trục trặc", "other": ""}, {"t": "accessible", "ctx": "phù hợp cho người khuyết tật", "other": "accessible: dễ tiếp cận; dễ hiểu"}, {"t": "patrons", "ctx": "khán giả, khách quen", "other": "patron: nhà bảo trợ"}, {"t": "wheelchairs", "ctx": "xe lăn", "other": ""}, {"t": "impossible to ignore", "ctx": "không thể làm ngơ", "other": ""}, {"t": "burst pipe", "ctx": "ống nước vỡ", "other": ""}, {"t": "flooded", "ctx": "làm ngập", "other": ""}, {"t": "backstage", "ctx": "hậu trường", "other": ""}, {"t": "relocate", "ctx": "chuyển địa điểm", "other": ""}, {"t": "productions", "ctx": "vở diễn", "other": "production: sự sản xuất"}, {"t": "auditorium", "ctx": "hội trường, khán phòng", "other": ""}, {"t": "remarkably patient", "ctx": "kiên nhẫn đáng nể", "other": ""}, {"t": "artistic director", "ctx": "giám đốc nghệ thuật", "other": ""}, {"t": "ramp", "ctx": "đường dốc (cho xe lăn)", "other": "ramp: đường dẫn lên cao tốc"}, {"t": "pledged to retain", "ctx": "cam kết giữ lại", "other": ""}, {"t": "distinctive features", "ctx": "nét đặc trưng, riêng biệt", "other": ""}, {"t": "ornate plaster ceiling", "ctx": "trần thạch cao trang trí cầu kỳ", "other": ""}, {"t": "illuminated marquee", "ctx": "biển hiệu có đèn trước rạp", "other": ""}, {"t": "theatergoers", "ctx": "người hay đi xem kịch", "other": ""}, {"t": "early supporters", "ctx": "những người ủng hộ đầu tiên", "other": ""}, {"t": "has already been pledged", "ctx": "đã được cam kết đóng góp", "other": ""}, {"t": "match", "ctx": "góp thêm số tiền bằng đúng khoản đó", "other": "match: trận đấu; hợp với"}, {"t": "dollar for dollar", "ctx": "một đô đổi một đô", "other": ""}, {"t": "donation", "ctx": "khoản quyên góp", "other": ""}, {"t": "contribute", "ctx": "đóng góp", "other": ""}, {"t": "engraved", "ctx": "được khắc (tên, chữ)", "other": ""}, {"t": "commemorative wall", "ctx": "bức tường ghi danh, tưởng niệm", "other": ""}, {"t": "longtime subscribers", "ctx": "khán giả mua vé dài hạn lâu năm", "other": "subscriber: người đăng ký (báo, kênh)"}, {"t": "uncomfortably", "ctx": "một cách khó chịu", "other": ""}, {"t": "expanded", "ctx": "được mở rộng", "other": ""}, {"t": "crowding", "ctx": "sự chen chúc", "other": ""}, {"t": "intermissions", "ctx": "giờ giải lao (giữa buổi diễn)", "other": ""}, {"t": "milestone", "ctx": "cột mốc", "other": ""}, {"t": "lobby", "ctx": "sảnh", "other": "lobby: vận động hành lang"}, {"t": "raised", "ctx": "quyên góp được (tiền)", "other": "raise: tăng; nuôi; nêu (vấn đề)"}], "links": {"drh-theater-q1": [["a fundraising effort", "a $2.4 million campaign"], ["repairs", "restore the Alcott Playhouse"]], "drh-theater-q2": [["does not work reliably", "frequent heating malfunctions"]], "drh-theater-q3": [["damaged by water", "a burst pipe flooded the backstage area"], ["Two performances were canceled", "relocate two productions"]], "drh-theater-q4": [["preserved", "pledged to retain"], ["A decorative ceiling", "ornate plaster ceiling"]], "drh-theater-q5": [["double individual donations", "match every individual donation, dollar for dollar"], ["up to a certain amount", "up to a total of $500,000"]]}, "lvl": "Khó", "qs": [{"id": "drh-theater-q1", "pos": 0, "prompt": "What is the purpose of the press release?", "options": ["To announce a new theater season", "To publicize a fundraising effort for repairs", "To introduce a new artistic director", "To report the sale of a building"], "answer": 1, "explain": "Tiêu đề và đoạn đầu: \"a $2.4 million campaign to restore the Alcott Playhouse\", sau đó kể số tiền đã cam kết, cách quyên góp → quảng bá đợt gây quỹ sửa nhà hát.", "skill": "Mục đích"}, {"id": "drh-theater-q2", "pos": 1, "prompt": "What is mentioned as a problem with the Alcott Playhouse?", "options": ["Its heating system does not work reliably.", "Its stage is too small.", "It has no parking area.", "Its tickets are too expensive."], "answer": 0, "explain": "\"frequent heating malfunctions\" = hệ thống sưởi hay trục trặc → không hoạt động ổn định.", "skill": "Paraphrase"}, {"id": "drh-theater-q3", "pos": 2, "prompt": "What happened at the theater last winter?", "options": ["Part of the building was damaged by water.", "Two performances were canceled.", "A new elevator was installed.", "The roof was replaced."], "answer": 0, "explain": "\"a burst pipe flooded the backstage area\" → một phần tòa nhà bị ngập nước. B là bẫy: hai vở được \"relocate\" (chuyển chỗ diễn), không bị hủy.", "skill": "Chi tiết"}, {"id": "drh-theater-q4", "pos": 3, "prompt": "What will be preserved during the renovation?", "options": ["The seating", "A decorative ceiling", "The heating system", "The backstage area"], "answer": 1, "explain": "\"pledged to retain... its ornate plaster ceiling\" → giữ lại trần trang trí. Ghế và hệ thống sưởi đều sẽ được thay hoặc thêm mới.", "skill": "Paraphrase"}, {"id": "drh-theater-q5", "pos": 4, "prompt": "What is indicated about the Lindqvist Foundation?", "options": ["It will double individual donations up to a certain amount.", "It has already donated $900,000.", "It owns the Alcott Playhouse.", "It will pay for a new marquee."], "answer": 0, "explain": "\"match every individual donation, dollar for dollar, up to a total of $500,000\" → góp thêm bằng đúng số người khác quyên = nhân đôi, có mức trần. B sai: 900.000 đô là của \"early supporters\".", "skill": "Paraphrase"}]}];
